import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BfWdyVj4.js";const u=JSON.parse('{"title":"Installing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1793093713000}'),o={name:"guide/install.md"};function n(r,e,d,l,h,c){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h1><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A Linux computer that&#39;s always on. A Raspberry Pi 4 or 5 is plenty.</li><li><a href="https://bun.sh" target="_blank" rel="noreferrer">Bun</a> (the installer adds it).</li><li>A web server with HTTPS. Browsers only allow the microphone over HTTPS; <a href="https://caddyserver.com" target="_blank" rel="noreferrer">Caddy</a> gets certificates for you, and the installer can set it up.</li><li>Ideally <a href="https://www.home-assistant.io" target="_blank" rel="noreferrer">Home Assistant</a>, and Docker or Podman for the voice. Without Home Assistant there&#39;s no voice, but <a href="/guide/displays#without-home-assistant">typed questions still work</a>.</li><li>A brain: <a href="https://claude.com/claude-code" target="_blank" rel="noreferrer">Claude Code</a> on your Claude subscription, or a model API (Anthropic, or an OpenAI-compatible one such as LM Studio, Ollama or OpenAI).</li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/froghub-assistant/froghub/master/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p><code>install.sh</code> works on Raspberry Pi OS, Debian and Ubuntu (apt), and on Fedora, RHEL, CentOS Stream, Rocky, Alma and Oracle Linux (dnf; it also sets up firewalld and SELinux for Caddy). It installs git, Bun, Caddy, tmux and rsync (and, if you say yes, Docker or Podman for the voice, and Claude Code), fetches Frog Hub to <code>~/froghub</code>, then runs <code>bun run setup</code>.</p><p>Already have it? <code>bun run setup</code> in the repo asks the same questions.</p><div class="tip custom-block"><p class="custom-block-title">See what it would do first</p><p><code>curl -fsSL … | sh -s -- --dry-run</code> asks the same questions and shows what it would install and change, without changing anything. If Frog Hub is already there, it goes on to setup&#39;s own <code>--dry-run</code>.</p></div><h2 id="what-setup-asks-and-does" tabindex="-1">What setup asks, and does <a class="header-anchor" href="#what-setup-asks-and-does" aria-label="Permalink to &quot;What setup asks, and does&quot;">​</a></h2><p>It asks for the site&#39;s address, Home Assistant&#39;s, the time zone, the children&#39;s names, a town for the weather, the admin PIN and which brain to use. Then it:</p><ul><li><p>writes <code>~/.config/froghub/</code> (<code>instance.json</code>, <code>weather.json</code>, <code>pin</code>);</p></li><li><p>installs the assistant as a systemd user service, either</p><ul><li><strong>Claude Code</strong> on Haiku with your Claude subscription (<code>setup/agent/</code> → <code>~/froghub-agent</code>, unit <code>froghub-agent</code>), or</li><li><strong>standalone</strong>, the API brain (<code>channel/standalone.ts</code>: the Anthropic API and/or an OpenAI-compatible one; keys in <code>~/.config/froghub/standalone.env</code>, rules in <code>~/.config/froghub/assistant.md</code>, unit <code>froghub-standalone</code>).</li></ul><p>Both serve the same <a href="/reference/http-api">HTTP API</a> and have the same tools;</p></li><li><p>asks for a <a href="/features/recipes">recipeapi.io</a> key and a <a href="/features/audio#sound-clips">Freesound</a> key (both optional);</p></li><li><p>builds the web app and copies it to the web root;</p></li><li><p>adds a site block to <code>/etc/caddy/Caddyfile</code> (it asks first and keeps a <code>.bak-froghub</code>) or prints it for you;</p></li><li><p>starts the voice containers (<code>setup/voice/compose.yaml</code>: openWakeWord, Whisper and Piper) and, with a Home Assistant token it doesn&#39;t keep, adds them to Home Assistant and creates the four <code>Frog Hub · &lt;Personality&gt;</code> pipelines.</p></li></ul><h3 id="voice-on-another-computer" tabindex="-1">Voice on another computer <a class="header-anchor" href="#voice-on-another-computer" aria-label="Permalink to &quot;Voice on another computer&quot;">​</a></h3><p>Any of the three voice services can run on another computer instead (Whisper on a faster PC, say): answer with its <code>host:port</code>, and setup offers to install it there over SSH (Docker or Podman too, if it has neither; its files go in <code>~/froghub-voice</code> there). <code>upgrade.sh</code> and <code>remove.sh</code> reach it the same way. Or run it there yourself, from a copy of the repo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VOICE_BIND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">0.0.0.0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup/voice/compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whisper</span></span></code></pre></div><h2 id="changing-things-later" tabindex="-1">Changing things later <a class="header-anchor" href="#changing-things-later" aria-label="Permalink to &quot;Changing things later&quot;">​</a></h2><p>Run <code>bun run setup</code> again: each answer defaults to what&#39;s set now, and <code>bun run setup --dry-run</code> shows what it would do without changing anything. The assistant&#39;s rules (<code>CLAUDE.md</code> or <code>assistant.md</code>) are only replaced if you say so, since they&#39;re yours to tweak.</p><p>Then open the site on each tablet and follow the welcome: see <a href="/guide/displays">Setting up a display</a>.</p>',17)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
